});

test('duplicate legacy resource paths are invalid and atomic', () => {
  const document = {
    format: 'transcript/1',
    options: {},
    sessions: [],
    resources: [
      { path: 'same', size: 1, mediaType: 'text/plain' },
      { path: 'same', size: 2, mediaType: 'application/octet-stream' },
    ],
  };

  assertFailureIsAtomic(
    seededArchive(),
    document,
    'INVALID_DOCUMENT',
  );
});

test('non-object documents are invalid and leave all state unchanged', async t => {
  for (const [name, document] of [
    ['null', null],
    ['array', []],
    ['string', 'document'],
    ['number', 42],
    ['boolean', false],
  ]) {
    await t.test(name, () => {
      const archive = seededArchive();
      const before = stateOf(archive);

      assert.deepEqual(restoreArchive(archive, document), {
        ok: false,
        error: 'INVALID_DOCUMENT',
      });
      assert.deepEqual(stateOf(archive), before);
    });
  }
});

test('unknown formats are unsupported and atomic', async t => {
  for (const format of ['transcript/0', 'transcript/3', '', 2, null]) {
    await t.test(String(format), () => {
      const document = {
        format,
        options: {},
        threads: [],
        attachments: {},
      };
      assertFailureIsAtomic(
        seededArchive(),
        document,
        'UNSUPPORTED_VERSION',
      );
    });
  }
});

