test('packArchive represents current public state and round-trips it', () => {
  const source = openArchive();

  assert.deepEqual(restoreArchive(source, legacyDocument()), {
    ok: true,
    imported: 2,
  });
  assert.deepEqual(restoreArchive(source, {
    format: 'transcript/2',
    options: {
      final: true,
      nested: [{ key: 'value' }],
    },
    threads: [
      {
        id: 'current-c',
        header: { subject: 'Current', labels: ['x', 'y'] },
        messages: [
          { speaker: 'user', text: null },
          { speaker: 'assistant', text: '' },
        ],
      },
    ],
    attachments: {
      'final/manifest-only.bin': {
        size: Number.MAX_SAFE_INTEGER,
        mediaType: 'application/octet-stream',
      },
    },
  }), {
    ok: true,
    imported: 1,
  });

  const packed = packArchive(source);
  assert.equal(packed.format, 'transcript/2');
  assert.deepEqual(packed.threads, readThreads(source));
  assert.deepEqual(packed.options, readOptions(source));
  assert.deepEqual(packed.attachments, readManifest(source));

  const packedBefore = clone(packed);
  const restored = openArchive();

  assert.deepEqual(restoreArchive(restored, packed), {
    ok: true,
    imported: 3,
  });
  assert.deepEqual(packed, packedBefore);
  assert.deepEqual(stateOf(restored), stateOf(source));
});
